"""Public static extension only. No bridge server, user data, or signing material."""
from pathlib import Path
import argparse,json,shutil
root=Path(__file__).resolve().parent.parent
parser=argparse.ArgumentParser();parser.add_argument('--dest',default='work/pages21');args=parser.parse_args()
target=(root/args.dest).resolve();assert target!=root and target.is_relative_to(root)
source=root/'outputs/owlbear';target.mkdir(parents=True,exist_ok=True)
names=['background.html','background.js','panel.html','panel.js','roll.html','roll.js','tools19.html','tools19.css','initiative21.css','theatre21.css','tools19.js','surface19.html','surface19.js','status18.html','status18.js','results21.html','results21.js','launcher21.html','launcher21.js','dice-effect19.html','dice-effect19.js','style.css','icon.svg','tools19.svg','heart19.svg','target19.svg','LICENSE-sdk.txt','LICENSE-suite19.txt','THIRD-PARTY19.txt']
base='https://feathercatttt.github.io/traveler-folio/'
for name in names:
 assert (source/name).is_file(),name
 shutil.copyfile(source/name,target/name)
for name in ['manifest.json','tools-manifest.json']:
 data=json.loads((source/name).read_text(encoding='utf8'))
 data['icon']=base+data['icon'].lstrip('/');data['background_url']=base+'background.html'
 for k in ['icon','popover']:data['action'][k]=base+data['action'][k].lstrip('/')
 (target/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
for name in ['d4.png','d6.png','d8.png','d10.png','d12.png','d20.png','d100.png','dice.mp3','cartoon.mp3']:
 (target/'suite19').mkdir(exist_ok=True);shutil.copyfile(source/'suite19'/name,target/'suite19'/name)
(target/'.nojekyll').write_text('',encoding='utf8')
(target/'index.html').write_text('''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>旅人手札 · 枭熊插件</title><link rel="stylesheet" href="tools19.css"><style>body{max-width:820px;margin:40px auto;padding:0 20px}h1{font-size:32px;margin:12px 0}h2{font-size:20px}section{margin:20px 0;padding:22px}a{color:#e6bd70}input{font-size:13px}ol{padding-left:22px;line-height:2}table{width:100%;border-collapse:collapse}td,th{padding:10px 5px;text-align:left;border-bottom:1px solid #5b4a38}button{margin-top:8px}</style></head><body><small>TRAVELER FOLIO · v0.23.0</small><h1>旅人手札 · 枭熊插件</h1><p>离线角色卡与独立跑团工具。DM 安装一次，房间成员刷新后即可使用。</p><section><h2>两个独立按钮</h2><label>角色速查<input id="card" readonly value="'''+base+'''manifest.json"></label><button data-copy="card">复制角色速查安装地址</button><label>跑团工具<input id="tools" readonly value="'''+base+'''tools-manifest.json"></label><button data-copy="tools">复制跑团工具安装地址</button><p id="notice" role="status"></p></section><section><h2>安装与连接</h2><ol><li>DM 在枭熊个人扩展列表中添加上述两个地址，并在房间扩展设置中启用。</li><li>已安装 localhost 旧版的房间，请停用旧版，避免两套后台同时处理。</li><li>“旅人手札”使用可固定的枭熊原生小卡，＋／− 缩放，× 关闭；跑团工具使用可移动的独立浮窗。</li><li>读取本机卡片与怪物库时先打开 EXE，小卡自动连接，不再打开额外连接窗口。若线上插件被浏览器限制，请 DM 停用线上角色速查并安装本地地址 http://localhost:17632/manifest.json；每位玩家先开 EXE 再进入房间。</li><li>小卡选择角色后，在地图选中对应 token，再点击“绑定”。怪物图鉴在“跑团工具 → 怪物”读取本机资料；手札中的怪物仓库可按物种、分类、等级与熟练加值筛选。</li></ol><p>角色资料保存在本机，GitHub Pages 只托管插件代码。骰子、先攻、立绘和场景工具可独立使用。首次把本地图鉴立绘分享到枭熊时，按图片选择器提示选入一次，后续可直接放置或拖入地图。</p></section><section><h2>功能与操作</h2><table><tr><th>功能</th><th>操作</th></tr><tr><td>骰子</td><td>表达式与优势/劣势，最终确认后投骰；右下角摘要、历史、回放、音效与排队开关。</td></tr><tr><td>目标</td><td>T 选择多个目标；成功投骰后清空。所有伤害只报结果，手动扣血。</td></tr><tr><td>生命速调</td><td>心形按钮打开小浮窗，跟随地图选择，先扣临时生命再扣 HP。</td></tr><tr><td>先攻</td><td>加入棋子 → 准备 → 投先攻 → 开始战斗。绑定手札的棋子联动先攻加值，DM 可改值、排序与添加占位。</td></tr><tr><td>演出</td><td>创建演出角色，设置立绘与差分，分享给玩家；勾选后开启直播。小窗左键上场、右键下场。</td></tr><tr><td>怪物图鉴</td><td>本机制作、上传立绘和多行动；读取后放置多个实例，每只生命值独立保存在 Stat Bubbles。</td></tr></table></section><p><a href="https://github.com/Feathercatttt/traveler-folio/releases/latest">下载 EXE / APK / 离线 HTML</a> · <a href="https://github.com/Feathercatttt/traveler-folio">源代码与反馈</a></p><p class="muted">AI 辅助生成和维护的代码。已做本地与模拟多人检查；真实枭熊多人房间、各类 GPU 和实体手机仍需实际反馈。中国不同网络访问 GitHub Pages 的情况可能不同。</p><script>document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const input=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(input.value);document.getElementById('notice').textContent='已复制，在枭熊扩展列表粘贴安装。';}catch{input.focus();input.select();document.getElementById('notice').textContent='请复制选中的安装地址。';}});</script></body></html>''',encoding='utf8')
assert not any(p.name in ['server.py','state.json','connect21.html'] or p.suffix in ['.pem','.p12'] for p in target.rglob('*'))
print('Built public Pages:',target,'files',len(list(target.rglob('*'))))
